<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {getAuthContextVersion} from '@/api/http'
import {useAuthStore} from '@/stores/auth'
import {useV3ChatRedPacketsStore} from '@/stores/v3ChatRedPackets'
import {packetInput,packetPrincipal,packetRisk,type PacketInput,type PacketType} from '@/api/v3-chat-red-packets'
import {fpConfirm} from '@/composables/useDialog'
const auth=useAuthStore(),store=useV3ChatRedPacketsStore(),emit=defineEmits<{close:[]}>(),type=ref<PacketType>('random'),money=ref(32),count=ref(2),message=ref('一起摸鱼'),recipients=ref(''),gesture=ref<number|string>(''),confirming=ref(false),error=ref('')
const frozen=computed(()=>store.busy||!!store.pending||confirming.value),perShare=computed(()=>type.value==='average'||type.value==='specify')
let abort:AbortController|null=null,submitted=''
const identity=()=>JSON.stringify([getAuthContextVersion(),!!auth.accessToken,auth.account?.oId||''])
function cancel(){abort?.abort();abort=null;confirming.value=false}
function input():PacketInput{const value:PacketInput={type:type.value,money:money.value,message:message.value};if(type.value==='specify')value.recipientIds=recipients.value.trim().split(/[,，\s]+/u).filter(Boolean);else if(type.value!=='rockPaperScissors')value.count=count.value;if(packetRisk(type.value))value.riskAccepted=true;if(type.value==='rockPaperScissors')value.gesture=gesture.value as number;return packetInput(value,auth.account?.oId||'')}
async function send(){if(!auth.accessToken||!auth.account?.oId||frozen.value)return;error.value='';let value:PacketInput;try{value=input()}catch(e){error.value=e instanceof Error?e.message:'红包参数不合法';return}cancel();const controller=new AbortController();abort=controller;const reader=identity();confirming.value=true
 const risk=value.type==='heartbeat'?' 心跳可能领取负积分并扣款，发送者也可参与。领取前余额至少为初始税后奖池。':value.type==='rockPaperScissors'?' 猜拳领取者可能扣除税后金额，胜者获奖、平局或败者会触发发送者退款，税额不退。发送者不能领取。':''
 const yes=await fpConfirm({title:packetRisk(value.type)?'确认红包金额与风险':'确认发红包',message:`将支付总计${packetPrincipal(value)}积分，税后奖池和税额以服务器回执为准。红包不自动到期或退款，未领完不能删除。${risk}是否确认？`,confirmText:packetRisk(value.type)?'接受风险并创建':'确认创建红包',signal:controller.signal})
 if(yes&&!controller.signal.aborted&&reader===identity()){submitted=JSON.stringify(value);await store.create(value)}if(abort===controller){abort=null;confirming.value=false}}
watch(type,value=>{gesture.value='';if(value==='heartbeat'&&count.value<5)count.value=5;if(value==='rockPaperScissors'&&money.value<256)money.value=256})
watch(()=>store.completed,command=>{if(command?.kind!=='create'||JSON.stringify(command.input)!==submitted)return;try{if(JSON.stringify(input())===submitted){message.value='';recipients.value='';submitted='';emit('close')}}catch{}})
watch(identity,()=>{cancel();message.value='';recipients.value='';gesture.value='';submitted=''},{flush:'sync'});onBeforeUnmount(cancel)
</script>
<template><form class="packet-editor" @submit.prevent="send"><label>类型<select v-model="type" :disabled="frozen"><option value="random">拼手气</option><option value="average">普通</option><option value="specify">专属</option><option value="heartbeat">心跳（可能扣积分）</option><option value="rockPaperScissors">猜拳（可能扣积分）</option></select></label><label>{{ perShare?'每份积分':'总积分' }}<input v-model.number="money" type="number" :min="type==='rockPaperScissors'?256:32" max="10240" step="1" :disabled="frozen" required /></label><label v-if="type!=='specify'&&type!=='rockPaperScissors'">份数<input v-model.number="count" type="number" :min="type==='heartbeat'?5:1" max="100" step="1" :disabled="frozen" required /></label><label v-if="type==='specify'">接收人用户ID（逗号分隔，最多100人）<input v-model="recipients" maxlength="2048" :disabled="frozen" required /></label><label v-if="type==='rockPaperScissors'">发送者出拳<select v-model.number="gesture" :disabled="frozen" required><option value="" disabled>请选择出拳</option><option :value="0">石头</option><option :value="1">剪刀</option><option :value="2">布</option></select></label><label>留言<input v-model="message" maxlength="4096" :disabled="frozen" /></label><p>留言按红包字符规则过滤，过滤后最多20个UTF-16单位。普通、专属按每份金额扣款，其他类型按总额扣款。</p><p v-if="error" role="alert">{{ error }}</p><div><button type="submit" :disabled="frozen">确认金额并创建红包</button><button type="button" @click="emit('close')">取消</button></div></form></template>
<style scoped lang="scss">.packet-editor{display:flex;flex-direction:column;gap:8px;padding:8px 0;min-width:0}label{display:flex;flex-direction:column;gap:4px;font-size:13px}input,select{box-sizing:border-box;width:100%;min-width:0}button,input,select{font:inherit;border:1px solid var(--fp-border);border-radius:5px;padding:6px;background:var(--fp-card);color:var(--fp-text)}button{margin-right:6px}p{font-size:12px;color:var(--fp-muted);margin:0}[role=alert]{color:#bd503c}button:disabled,input:disabled,select:disabled{opacity:.5}</style>
